import { useEffect, useState } from "react";
import "./App.css";

const initialTransactions = [
    {
        type: "deposit",
        amount: 1000,
        date: new Date(),
    },
    {
        type: "buy",
        stock: "TSLA",
        shares: 10,
        price: 274,
        amount: 2740,
        date: new Date(),
    },
];

function App() {
    const [transactions, setTransactions] = useState(initialTransactions);
    const [balance, setBalance] = useState(0);

    function handleCreateTransaction(type, stock, shares, price, amount, date) {
        const newTransaction = {
            type,
            stock,
            shares,
            price,
            amount,
            date,
        };
        setTransactions((cur) => [...cur, newTransaction]);
    }

    useEffect(() => {
        console.log(transactions);
    }, [transactions]);

    return (
        <div className="App">
            <h1>Trading Journal</h1>
            <Balances balance={balance} />
            <TradeForm onCreateTransaction={handleCreateTransaction} />
            <DepositAndWithdrawalForm
                onCreateTransaction={handleCreateTransaction}
            />
            <TransactionTable />
            <TradesTable />
        </div>
    );
}

function Balances({ balance }) {
    return (
        <div>
            <label>Account Balance</label>
            <input type="text" disabled value={balance} />
        </div>
    );
}

function TradeForm({ onCreateTransaction }) {
    const [transactionType, setTransactionType] = useState("buy");
    const [stock, setStock] = useState("");
    const [shares, setShares] = useState("");
    const [price, setPrice] = useState("");
    const [date, setDate] = useState(new Date().toLocaleDateString());

    const total = shares * price;

    function handleSubmit(e) {
        e.preventDefault();
        if (!transactionType || !stock || !shares || !price || !date) return;

        onCreateTransaction(transactionType, stock, shares, price, total, date);
    }

    return (
        <form className="form" onSubmit={(e) => handleSubmit(e)}>
            <h2>Enter a Trade</h2>
            <div>
                <input
                    type="radio"
                    id="buy"
                    value="buy"
                    checked={transactionType === "buy"}
                    onChange={() => setTransactionType("buy")}
                />
                <label htmlFor="buy">Buy</label>
                <input
                    type="radio"
                    id="sell"
                    value="sell"
                    checked={transactionType === "sell"}
                    onChange={() => setTransactionType("sell")}
                />
                <label htmlFor="sell">Sell</label>
            </div>
            <div>
                <label>Stock</label>
                <input
                    type="text"
                    value={stock}
                    onChange={(e) => setStock(e.target.value)}
                />
            </div>
            <div>
                <label>Shares</label>
                <input
                    type="text"
                    value={shares}
                    onChange={(e) => setShares(e.target.value)}
                />
            </div>
            <div>
                <label>Price</label>
                <input
                    type="text"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                />
            </div>
            <div>
                <label>Total</label>
                <input type="text" disabled value={total} />
            </div>
            <div>
                <label>Date</label>
                <input
                    type="date"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                />
            </div>
            <button>Submit</button>
        </form>
    );
}

function DepositAndWithdrawalForm({ onCreateTransaction }) {
    const [transactionType, setTransactionType] = useState("deposit");
    const [amount, setAmount] = useState(0);
    const [date, setDate] = useState(new Date().toLocaleDateString());

    function handleSubmit(e) {
        e.preventDefault();
        console.log(transactionType);
        console.log(amount);
        console.log(date);
        onCreateTransaction(transactionType, null, null, null, amount, date);
    }

    function handleChangeAmount(value) {
        if (isNaN(value)) return;
        setAmount(Number(value));
    }

    return (
        <form className="form" onSubmit={(e) => handleSubmit(e)}>
            <h2>Deposit or Withdraw</h2>
            <div>
                <input
                    type="radio"
                    id="deposit"
                    value="deposit"
                    checked={transactionType === "deposit"}
                    onChange={() => setTransactionType("deposit")}
                />
                <label htmlFor="deposit">Deposit</label>
                <input
                    type="radio"
                    id="withdraw"
                    value="withdraw"
                    checked={transactionType === "withdraw"}
                    onChange={() => setTransactionType("withdraw")}
                />
                <label htmlFor="withdraw">Withdraw</label>
            </div>
            <div>
                <label>Amount</label>
                <input
                    type="text"
                    value={amount}
                    onChange={(e) => handleChangeAmount(e.target.value)}
                />
            </div>
            <div>
                <label>Date</label>
                <input
                    type="date"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                />
            </div>
            <button>Submit</button>
        </form>
    );
}

function TransactionTable() {
    return (
        <div>
            <h2>Transactions</h2>
            <table></table>
        </div>
    );
}

function TradesTable() {
    return (
        <div>
            <h2>Trades</h2>
            <table></table>
        </div>
    );
}

export default App;
